 function loadForm(){const o=selectedObject();reviewFormBaseline=null;if(!o)return;$('objectAlias').value=o.alias||'';const review=o.reviews.at(-1);$('reviewerName').value=review?.reviewer||'';$('reviewNotes').value='';$('coverageScope').value='unknown';for(const d of C.dimensions)$('review-'+d).value='pending';reviewFormBaseline=JSON.stringify(reviewFields());const host=$('objectReviewHistory');host.replaceChildren();for(const r of o.reviews.slice().reverse()){const p=document.createElement('p');p.className='meta';p.textContent=`v${r.revision} · ${r.at} · ${r.reviewer}：${C.dimensions.map(d=>names[d]+'='+r.checks[d]).join('；')}。覆盖范围 ${r.coverage_scope||'unknown'}。${r.notes}`;host.append(p);}}
